  "name": "toggle_blinds",
  "description": "Toggle one or more blinds/shades devices between open and closed states. This tool changes the state of window coverings like blinds, shades, or curtains by checking their current position and doing the opposite action. If currently open (any position above 0%), it will fully close them (0%). If currently closed (0%), it will fully open them (100%).",
  "parameters": {
    "type": "object",
    "properties": {
      "endpoints": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "description": "List of device endpoint IDs to toggle. Each endpoint must correspond to a blinds/shades device that supports the toggle API."
      }
    },
    "required": ["endpoints"]
  },
  "error_cases": [
    "No devices specified: The endpoints parameter is empty or not provided.",
    "Device not found: One or more specified endpoints do not exist in the current user's home.",
    "API not supported: One or more devices do not support the toggle API.",
    "State update failure: The device state could not be updated due to a system error.",
    "Device obstruction: Some devices may fail to close if they detect an obstruction in the path."
  ]
